    def build_connector_meta(
        self, scheduler_output: SchedulerOutput,
    ) -> KVConnectorMetadata:
        """Package pending imports/exports into metadata for the worker.

        Block IDs are extracted from scheduler_output.scheduled_new_reqs
        since the V1 API doesn't pass blocks to update_state_after_alloc.
        """
        # Build block_id map from scheduler_output
        block_id_map: dict[str, list[int]] = {}
        if scheduler_output is not None:
            for new_req in getattr(scheduler_output, "scheduled_new_reqs", []):
                block_id_map[new_req.req_id] = list(new_req.block_ids)
            for cached_req in getattr(scheduler_output, "scheduled_cached_reqs", []):
                if cached_req.new_block_ids:
                    block_id_map.setdefault(cached_req.req_id, []).extend(
                        cached_req.new_block_ids
                    )

        pending_imports = []
        for req_id, info in self._pending_imports.items():
            lookup = info["lookup"]
            local_block_ids = block_id_map.get(req_id, [])
            pending_imports.append(PendingImport(
                request_id=req_id,
                transfer_address=lookup.transfer_address,
                source_blocks=lookup.engine_block_ids,
                local_block_ids=local_block_ids,
                num_tokens=lookup.matched_tokens,
            ))

        pending_exports = []
        for req_id, info in self._pending_exports.items():
            block_ids = block_id_map.get(req_id, [])
            if block_ids:
                pending_exports.append(PendingExport(
                    request_id=req_id,
                    prompt_token_ids=info["prompt_token_ids"],
                    block_ids=block_ids,
                ))

        # Clear pending state — it's been packaged into metadata
        self._pending_imports.clear()
        self._pending_lookups.clear()
        self._pending_exports.clear()

        return KvfConnectorMetadata(
            pending_imports=pending_imports,
            pending_exports=pending_exports,
        )

